import hashlib, json, os, time, urllib.parse, urllib.request
from datetime import datetime
from zoneinfo import ZoneInfo

SIGNS = (("♈️","Овен","смело берёт инициативу"),("♉️","Телец","ценит надёжность и спокойствие"),("♊️","Близнецы","быстро замечают новые возможности"),("♋️","Рак","тонко чувствует настроение людей"),("♌️","Лев","умеет вдохновлять окружающих"),("♍️","Дева","видит важные детали"),("♎️","Весы","ищет точку равновесия"),("♏️","Скорпион","не боится сложных разговоров"),("♐️","Стрелец","видит перспективу шире других"),("♑️","Козерог","умеет превращать план в результат"),("♒️","Водолей","находит нестандартное решение"),("♓️","Рыбы","доверяет творческой интуиции"))
THEMES=("утро подходит для точных решений, а во второй половине дня лучше не торопить события","день начнётся активно; ближе к вечеру появится повод пересмотреть планы","обстоятельства подскажут, на чём действительно стоит сосредоточиться","внимание к мелочам убережёт от лишней суеты и даст хороший результат","случайная встреча или разговор могут открыть интересную возможность","самые удачные перемены начнутся с небольшого, но своевременного шага")
WORK=("В работе не берите на себя чужие обязательства: закончите главное и только потом расширяйте список задач.","Деловые переговоры пройдут продуктивно, если говорить прямо и заранее подготовить аргументы.","День хорош для документов, расчётов и решений, которые давно требовали порядка.","Не отказывайтесь от помощи коллег: вместе вы быстрее увидите практичный выход.")
LOVE=("В личных отношениях важнее всего будет спокойный тон. Не скрывайте симпатию, но и не требуйте немедленного ответа.","Близкий человек может нуждаться в вашем внимании сильнее, чем показывает. Небольшой знак заботы многое изменит.","Для новых знакомств день благоприятен, особенно если не пытаться произвести впечатление любой ценой.","Не обсуждайте старые обиды на эмоциях: вечер лучше посвятить тому, что возвращает тепло и доверие.")
ADVICE=("Полезно оставить запас времени между встречами.","Проверьте важные цифры и адреса дважды.","Вечером дайте себе полноценную паузу от дел.","Слушайте факты, а не тревожные догадки.")
def pick(items,day,sign,key): return items[int(hashlib.sha256(f"{day}:{sign}:{key}".encode()).hexdigest(),16)%len(items)]
def text(day,icon,sign,trait):
 return f"{icon} <b>{sign} — {day:%d.%m.%Y}</b>\n\nСегодня {trait}. {pick(THEMES,day,sign,'t').capitalize()}. Не пытайтесь контролировать всё сразу: один ясный приоритет принесёт больше пользы, чем поспешные решения.\n\n<b>Дела и деньги.</b> {pick(WORK,day,sign,'w')}\n\n<b>Отношения.</b> {pick(LOVE,day,sign,'l')}\n\n✨ <b>Совет дня:</b> {pick(ADVICE,day,sign,'a')}\n\n#гороскоп #{sign.lower()}"
def send(data):
 token=os.environ['TELEGRAM_BOT_TOKEN'].strip(); req=urllib.request.Request(f"https://api.telegram.org/bot{token}/sendMessage",data=urllib.parse.urlencode(data).encode(),method='POST')
 with urllib.request.urlopen(req,timeout=30) as r:
  if not json.loads(r.read()).get('ok'): raise RuntimeError('Telegram rejected the post')
day=datetime.now(ZoneInfo('Europe/Moscow')).date()
for icon,sign,trait in SIGNS:
 send({'chat_id':'@proastrologi','text':text(day,icon,sign,trait),'parse_mode':'HTML'}); time.sleep(1)
